-- =====================================================================
-- TalentoMDD · Datos iniciales (generados a partir del prototipo)
-- Seguro de ejecutar varias veces: borra y vuelve a crear los datos de ejemplo.
-- Las fechas límite se calculan desde la fecha en que ejecutes este script.
-- =====================================================================

delete from public.offers where id::text like '00000000-0000-4000-9000-%';
delete from public.companies where id::text like '00000000-0000-4000-8000-%';
delete from public.news;

on conflict (id) do update set name = excluded.name;

on conflict (id) do update set faculty_id = excluded.faculty_id, name = excluded.name, icon = excluded.icon;



